# A minimal LangChain-style chain (without the actual library)

def build_chain(prompt_template, llm_fn, parser_fn):
    def chain(inputs):
        prompt = prompt_template.format(**inputs)
        raw = llm_fn(prompt)
        return parser_fn(raw)
    return chain

prompt_template = "Classify sentiment of: {text}\nAnswer with one word."

def fake_llm(prompt):
    if "love" in prompt.lower():
        return "Positive"
    return "Negative"

def parser(raw):
    return raw.strip()

chain = build_chain(prompt_template, fake_llm, parser)
print(chain({"text": "I love this product"}))
print(chain({"text": "It broke on day one"}))
